('Installation française à Cotonou', 'installation-francaise-cotonou-BJ', '01863-01-01', '01863-12-31', 'Le roi Glèlè autorise les Français à établir une présence à Cotonou.', NULL, 17),
('Traité franco-dahoméen de 1878', 'traite-franco-dahomeen-1878-BJ', '01878-01-01', '01878-12-31', 'Un nouvel accord renforce les intérêts français sur la côte du Dahomey.', NULL, 14),
('Protectorat français sur Porto-Novo', 'protectorat-francais-porto-novo-1882-BJ', '01882-01-01', '01882-12-31', 'Le souverain de Porto-Novo signe un nouvel accord de protectorat avec la France.', NULL, 14),
('Première guerre franco-dahoméenne', 'premiere-guerre-franco-dahomeenne-BJ', '01890-02-01', '01890-10-04', 'Le royaume du Dahomey affronte les forces françaises dans le cadre du conflit pour le contrôle du littoral.', NULL, 6),
('Seconde guerre franco-dahoméenne', 'seconde-guerre-franco-dahomeenne-BJ', '01892-07-01', '01894-01-15', 'Les forces françaises affrontent le royaume du Dahomey et progressent jusqu’à Abomey.', NULL, 6),
('Chute du roi Béhanzin', 'chute-roi-behanzin-BJ', '01894-01-15', '01894-01-15', 'La prise d’Abomey entraîne la défaite du roi Béhanzin et la fin de l’indépendance du royaume du Dahomey.', NULL, 12),
('Création de la colonie du Dahomey et dépendances', 'creation-colonie-dahomey-BJ', '01894-06-22', '01894-06-22', 'La France crée officiellement la colonie du Dahomey et dépendances après la conquête du royaume.', NULL, 17),
('Rattachement au Soudan français puis à l’Afrique occidentale française', 'rattachement-afrique-occidentale-francaise-BJ', '01899-01-01', '01899-12-31', 'Le Dahomey est intégré à l’organisation administrative de l’Afrique occidentale française.', NULL, 12),
('Création du territoire du Dahomey', 'creation-territoire-dahomey-BJ', '01946-01-01', '01946-01-01', 'Le Dahomey devient un territoire d’outre-mer français après la réorganisation de l’empire colonial.', NULL, 17),
('Proclamation de la République du Dahomey', 'proclamation-republique-dahomey-BJ', '01958-12-04', '01958-12-04', 'Le Dahomey devient une république autonome au sein de la Communauté française.', NULL, 22),
('Indépendance du Dahomey', 'independance-dahomey-BJ', '01960-08-01', '01960-08-01', 'Le Dahomey accède à la souveraineté internationale et devient un État indépendant.', NULL, 11),
('Coup d’État de Christophe Soglo', 'coup-etat-christophe-soglo-BJ', '01963-10-28', '01963-10-28', 'Le colonel Christophe Soglo renverse le président Hubert Maga et met fin au premier gouvernement élu de l’indépendance.', NULL, 10),
('Coup d’État de Mathieu Kérékou', 'coup-etat-mathieu-kerekou-BJ', '01972-10-26', '01972-10-26', 'Mathieu Kérékou prend le pouvoir à la suite d’un coup d’État militaire et ouvre une nouvelle période politique.', NULL, 10),
('Création de la République populaire du Bénin', 'creation-republique-populaire-benin-BJ', '01975-11-30', '01975-11-30', 'Le Dahomey est rebaptisé République populaire du Bénin et adopte officiellement une orientation marxiste-léniniste.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des sociétés tswana', 'developpement-societes-tswana-BW', '01000-01-01', '01400-12-31', 'Les sociétés tswana développent progressivement des structures politiques organisées autour de chefferies et de communautés appelées merafe.', NULL, 17),
('Expansion de la culture du Grand Zimbabwe au Botswana', 'expansion-culture-grand-zimbabwe-BW', '01200-01-01', '01400-12-31', 'La culture du Grand Zimbabwe étend son influence commerciale et culturelle jusque dans l’est du territoire de l’actuel Botswana.', NULL, 17),
('Développement du royaume de Butua', 'developpement-royaume-butua-BW', '01450-01-01', '01650-12-31', 'Après le déclin du Grand Zimbabwe, le royaume de Butua devient une puissance régionale dans l’espace correspondant notamment à l’est du Botswana.', NULL, 16),
('Formation des chefferies tswana', 'formation-chefferies-tswana-BW', '01600-01-01', '01800-12-31', 'Plusieurs chefferies tswana importantes se consolident, notamment les Bakwena, Bangwaketse, Bakgatla et Bangwato.', NULL, 16),
('Expansion des Ngwato sous Khama', 'expansion-ngwato-khama-BW', '01840-01-01', '01870-12-31', 'Les Bangwato renforcent leur puissance politique dans le nord-est du territoire sous l’autorité de Khama III.', NULL, 5),
